(5010286, 730707, 98141, '<td valign="top">Very nice interpretation, and good job peeling! A plainer surface might have improved the pic even more.</td>', 'Very nice interpretation, and good job peeling! A plainer surface might have improved the pic even more.', '2008-10-15 17:18:11.000000', NULL, 1),
(5010289, 730689, 98141, '<td valign="top">Gross, but I like it! Nice background, too. How do you tell which end it''s coming out of with an avacado? Could be something other than vomit... haha.</td>', 'Gross, but I like it! Nice background, too. How do you tell which end it''s coming out of with an avacado? Could be something other than vomit... haha.', '2008-10-15 17:18:52.000000', NULL, 1),
(5010291, 730410, 98141, '<td valign="top">Aha! This was the idea I thought of for this challenge, though I didn''t enter it, I think you executed it nicely. I like that the frame is filled with other bears, and the colors are perfect for the season.</td>', 'Aha! This was the idea I thought of for this challenge, though I didn''t enter it, I think you executed it nicely. I like that the frame is filled with other bears, and the colors are perfect for the season.', '2008-10-15 17:20:02.000000', NULL, 1),
(5010293, 730439, 98141, '<td valign="top">I almost didn''t catch that the shirt is inside out. I like the pic, but something with seams of a darker/different color than the fabric might have made the inside-out-ness a little stronger.</td>', 'I almost didn''t catch that the shirt is inside out. I like the pic, but something with seams of a darker/different color than the fabric might have made the inside-out-ness a little stronger.', '2008-10-15 17:21:04.000000', NULL, 1),
