(5010306, 730999, 98141, '<td valign="top">I think this in color to show the red of the membranes in the eyes would have made it more effective and easier to see.</td>', 'I think this in color to show the red of the membranes in the eyes would have made it more effective and easier to see.', '2008-10-15 17:27:59.000000', NULL, 1),
(5010310, 730920, 98141, '<td valign="top">I like the idea, I think the execution leaves a little to be desired. Too much of the pic for me is out of focus.</td>', 'I like the idea, I think the execution leaves a little to be desired. Too much of the pic for me is out of focus.', '2008-10-15 17:29:44.000000', NULL, 1),
(5010319, 730114, 98141, '<td valign="top">I enjoy this pic, but for reasons I can''t explain. It gives me the heebie jeebies (sp?) in an artsy kind of way.</td>', 'I enjoy this pic, but for reasons I can''t explain. It gives me the heebie jeebies (sp?) in an artsy kind of way.', '2008-10-15 17:33:04.000000', NULL, 1),
(5010324, 731060, 98141, '<td valign="top">If the background had been more starkly white to contrast the chocolate, I thik I would enjoy this more - but then I''m not sure if we would be able to enjoy the ooze so much.</td>', 'If the background had been more starkly white to contrast the chocolate, I thik I would enjoy this more - but then I''m not sure if we would be able to enjoy the ooze so much.', '2008-10-15 17:34:14.000000', NULL, 1),
(5010329, 730061, 98141, '<td valign="top">I don''t understand how this represents inside out, nor do I care much for the post-processing.</td>', 'I don''t understand how this represents inside out, nor do I care much for the post-processing.', '2008-10-15 17:35:58.000000', NULL, 1),
(5010334, 731148, 98141, '<td valign="top">Wow, I have no idea what I''m looking at, I feel as though I''m about to be engulfed by a yogurt monster! I like the lighting a lot.</td>', 'Wow, I have no idea what I''m looking at, I feel as though I''m about to be engulfed by a yogurt monster! I like the lighting a lot.', '2008-10-15 17:36:38.000000', NULL, 1),
