(5012569, 731039, 91379, '<td valign="top">Great idea !</td>', 'Great idea !', '2008-10-17 16:10:48.000000', NULL, 1),
(5012753, 731153, 47470, '<td valign="top">I love the idea, but the background is a bit distracting.  A quick pass of an iron over the sheet and an extra light aimed at it to blow it out would clean up the background a lot!  Still a very cute idea!</td>', 'I love the idea, but the background is a bit distracting.  A quick pass of an iron over the sheet and an extra light aimed at it to blow it out would clean up the background a lot!  Still a very cute idea!', '2008-10-17 18:50:12.000000', NULL, 1),
